input.new_string:
/**
 * Removal is a soft delete, and it is subject to the same last-owner rule as a
 * demotion — a removed owner is a demotion to "no role at all". A removed
 * member also loses every live issue still assigned to them; archived issues
 * keep their assignee, since they are no longer anyone's active work.
 */
export async function removeMember(
  actor: Actor,
  input: RemoveMemberInput,
): Promise<Member> {
  assertOrgScope(actor, input.orgId);

  const member = requireFound(
    await memberRepo.findMemberById(input.orgId, input.memberId),
    "Member",
    input.memberId,
  );
  assertCan(actor, "member:remove", memberResource(member));

  await assertLastOwnerRetained(input.orgId, input.memberId, "member");

  const removed = await memberRepo.archiveMember(input.orgId, input.memberId);

  await unassignLiveIssues(actor, input.orgId, removed.userId);

  await emit("member.removed", {
    ...actorEnvelope(actor),
    memberId: removed.id,
    userId: removed.userId,
  });

  return removed;
}

/**
 * Clears the assignee on every live issue `userId` still held, publishing one
 * `issue.unassigned` per issue with `actor` as the actor. Archived issues are
 * excluded by `listIssues`'s default scope, so they keep their assignee.
 */
async function unassignLiveIssues(
  actor: Actor,
  orgId: OrgId,
  userId: UserId,
): Promise<void> {
  let cursor: string | null = null;

  for (;;) {
    const page = await issueRepo.listIssues({
      orgId,
      assigneeId: userId,
      limit: ISSUE_SCAN_LIMIT,
      cursor,
    });

    for (const issue of page.items) {
      await issueRepo.setIssueAssignee(orgId, issue.id, null);
      await emit("issue.unassigned", {
        ...actorEnvelope(actor),
        issueId: issue.id,
        projectId: issue.projectId,
        previousAssigneeId: userId,
      });
    }

    if (page.nextCursor === null) break;
    cursor = page.nextCursor;
  }
}

